package android.media.session;import android.media.MediaMetadata;public class MediaController {public final Object token=new Object();public PlaybackState state=new PlaybackState(3);public MediaMetadata metadata=new MediaMetadata();public final TransportControls controls=new TransportControls();public String getPackageName(){return "com.shihab.diplay";}public Object getSessionToken(){return token;}public PlaybackState getPlaybackState(){return state;}public MediaMetadata getMetadata(){return metadata;}public TransportControls getTransportControls(){return controls;}public static class TransportControls {public int next,previous,play,pause;public void skipToNext(){next++;}public void skipToPrevious(){previous++;}public void play(){play++;}public void pause(){pause++;}}}
